  /* ------------------------------------------------------------------
   * weakPhrases: p is lowercase; s = stronger alternatives.
   * ------------------------------------------------------------------ */
  weakPhrases: [
    { p: "responsible for", s: ["Led", "Owned", "Managed", "Drove"], why: "Describes duties, not impact. Say what you achieved." },
    { p: "responsibilities included", s: ["Delivered", "Owned", "Managed"], why: "Reads like a job description; lead with outcomes instead." },
    { p: "duties included", s: ["Delivered", "Managed", "Executed"], why: "Reads like a job description; lead with outcomes instead." },
    { p: "worked on", s: ["Built", "Developed", "Delivered", "Implemented"], why: "Vague. Name your specific contribution and its result." },
    { p: "worked with", s: ["Partnered with", "Collaborated with", "Coordinated with"], why: "Vague. Say what the collaboration achieved." },
    { p: "helped with", s: ["Contributed to", "Co-led", "Enabled"], why: "Understates your role. Clarify exactly what you did." },
    { p: "helped", s: ["Enabled", "Accelerated", "Supported", "Contributed to"], why: "Understates your role. Clarify exactly what you did." },
    { p: "assisted with", s: ["Supported", "Co-delivered", "Contributed to"], why: "Sounds secondary. Describe your own actions and results." },
    { p: "assisted", s: ["Supported", "Enabled", "Contributed to"], why: "Sounds secondary. Describe your own actions and results." },
    { p: "involved in", s: ["Contributed to", "Drove", "Executed", "Delivered"], why: "Does not say what you actually did." },
    { p: "participated in", s: ["Contributed to", "Collaborated on", "Co-led"], why: "Passive. Highlight your specific contribution." },
    { p: "was part of", s: ["Contributed to", "Co-delivered", "Collaborated on"], why: "Passive. State your role and what you delivered." },
    { p: "tasked with", s: ["Led", "Delivered", "Owned"], why: "Focuses on the assignment, not the outcome." },
    { p: "in charge of", s: ["Led", "Directed", "Oversaw", "Headed"], why: "Wordy. Use a strong leadership verb and add scope." },
    { p: "handled", s: ["Managed", "Resolved", "Processed", "Oversaw"], why: "Generic. Add volume, scope or result (e.g. 120 tickets/week)." },
    { p: "dealt with", s: ["Resolved", "Managed", "Navigated"], why: "Negative and vague phrasing." },
    { p: "took care of", s: ["Managed", "Maintained", "Administered"], why: "Informal. Use a precise verb." },
    { p: "utilized", s: ["Used", "Applied", "Leveraged"], why: "Inflated word; 'used' or 'applied' is clearer." },
    { p: "successfully", s: ["Delivered", "Achieved", "Completed"], why: "Redundant. The result itself proves success." },
    { p: "managed to", s: ["Achieved", "Delivered", "Secured"], why: "Implies luck or struggle rather than capability." },
    { p: "tried to", s: ["Drove", "Pursued", "Initiated"], why: "Suggests failure. State what you did and what you learned." },
    { p: "attempted", s: ["Initiated", "Piloted", "Tested"], why: "Implies you did not succeed." },
    { p: "familiar with", s: ["Proficient in", "Used", "Applied"], why: "Weak skill claim. Show where you applied it." },
    { p: "exposure to", s: ["Applied", "Used", "Worked hands-on with"], why: "Implies passive contact, not real skill." },
    { p: "basic knowledge of", s: ["Working knowledge of", "Applied", "Trained in"], why: "Undersells you. List only skills you can discuss confidently." },
    { p: "team player", s: ["Collaborated", "Partnered", "Aligned"], why: "Cliche. Show collaboration with a concrete example." },
    { p: "hard worker", s: ["Delivered", "Exceeded", "Achieved"], why: "Unprovable claim. Show results instead." },
    { p: "hard-working", s: ["Delivered", "Exceeded", "Achieved"], why: "Unprovable claim. Show results instead." },
    { p: "detail-oriented", s: ["Ensured accuracy", "Reduced errors", "Audited"], why: "Cliche. Prove it with an accuracy or error-rate metric." },
    { p: "go-getter", s: ["Initiated", "Launched", "Pioneered"], why: "Informal buzzword. Show initiative with an example." },
    { p: "results-driven", s: ["Delivered", "Achieved", "Increased"], why: "Buzzword. State the results themselves." },
    { p: "results-oriented", s: ["Delivered", "Achieved", "Increased"], why: "Buzzword. State the results themselves." },
    { p: "self-motivated", s: ["Initiated", "Launched", "Drove"], why: "Claim without proof. Show initiative with an example." },
    { p: "passionate about", s: ["Built", "Championed", "Advocated"], why: "Overused. Show passion through what you did." },
    { p: "think outside the box", s: ["Innovated", "Reimagined", "Devised"], why: "Cliche. Describe the creative solution instead." },
    { p: "strong communication skills", s: ["Presented", "Negotiated", "Briefed"], why: "Claim without proof. Show a communication win." },
    { p: "various", s: ["Multiple (specify)", "12+", "Cross-functional"], why: "Vague. Quantify or name them." },
    { p: "etc", s: ["List 2-3 specifics"], why: "Signals incomplete thinking. Name what matters and stop." },
    { p: "a lot of", s: ["Numerous", "[specific number]"], why: "Informal and vague. Quantify it." },
    { p: "in order to", s: ["To"], why: "Wordy. Shorten to 'to'." },
    { p: "on a daily basis", s: ["Daily"], why: "Wordy. Use 'daily' or quantify frequency." },
    { p: "synergy", s: ["Collaboration", "Alignment", "Integration"], why: "Corporate jargon that hides the real action." }
  ],

